int main(void) {
    int price;
    int count = 0;
    long long sum = 0;
    scanf("%d", &price);
    while (price != 0) {
        sum += price;
        count++;
        scanf("%d", &price);
    }
    double average = 0.0;
    if (count > 0) {
        average = (double)sum / count;
    }
    printf("%d %lld %.2f\n", count, sum, average);
    return 0;
}

