#include <stdio.h>

int main(void) {
    int x;
    scanf("%d", &x);
    int max = x;
    int count = 0;
    while (x != 0) {
        if (x > max) {
            max = x;
            count = 1;
        } else if (x == max) {
            count++;
        }
        scanf("%d", &x);
    }
    printf("%d %d\n", max, count);
    return 0;
}

